  "checked_claims": [
    {
      "claim_id": "binding-check",
      "note": "ATT-0065 packet_id C66-001-v4, packet_sha256 39e87ba7e3784b681616f7a38db13eb7216cbd1fd11acb3a1fff2c20211f9a0a, packet_binding_sha256 76cc8a6d6ca02a2a9b1d7857fa11d7278f9732fa823f7be67dd51a354645bcc7, target dictionary, and theorem_statement all match TASK.json exactly. Web-evidence stage was unavailable; verdict rests on supplied local sources only.",
